// Auto Mix test fixtures: a catalog with the Krypt De-Esser (catalog.gen.json is regenerated by the lead), a
// small project (kick, bass, snare, hats, keys, lead, vocals, a drum bus) and synthetic measurements.
import { CATALOG } from '@shared/plugins/catalog';
import type { PluginCatalog } from '@shared/plugins/types';
import { DocHost } from '@shared/doc/DocHost';
import { createDefaultProject } from '@shared/schema/factory';
import type { Bands } from '@shared/automix/roles';
import type { InsertMeasure, PlanMeasure } from '@shared/automix/plan';

/** CATALOG + krypt.deesser exactly as engine/crates/dsp/src/effects/deesser.rs describes it. */
export function automixCatalog(): PluginCatalog {
  const cat = structuredClone(CATALOG) as PluginCatalog;
  if (!cat.plugins.some((p) => p.id === 'krypt.deesser')) {
    cat.plugins.push({
      id: 'krypt.deesser',
      name: 'Krypt De-Esser',
      kind: 'effect',
      category: 'Dynamics',
      description: 'Split-band de-esser for vocals.',
      params: [
        { id: 'frequency', name: 'Frequency', min: 4000, max: 10000, default: 6000, unit: 'Hz', scale: 'log', group: 'De-esser' },
        { id: 'threshold', name: 'Threshold', min: -60, max: 0, default: -30, unit: 'dB', scale: 'linear', group: 'De-esser' },
        { id: 'range', name: 'Range', min: 0, max: 24, default: 8, unit: 'dB', scale: 'linear', group: 'De-esser' },
        { id: 'listen', name: 'Listen', min: 0, max: 1, default: 0, unit: '', scale: 'linear', step: 1, options: ['Off', 'On'], group: 'De-esser' },
        { id: 'mix', name: 'Mix', min: 0, max: 1, default: 1, unit: '%', scale: 'linear', group: 'Output' },
      ],
      defaultMix: 1,
    } as PluginCatalog['plugins'][number]);
  }
  return cat;
}

export const NAMES = ['Kick', 'Bass', 'Snare', 'Hats', 'Keys', 'Lead', 'Vocals'] as const;
export type PartName = (typeof NAMES)[number] | 'Drum Bus';

/** A project with one insert per part (no channels), the drum parts through a "Drum Bus", the default master limiter. */
export function mixDoc(opts: { drumBus?: boolean; vocals?: boolean; catalog?: PluginCatalog } = {}): { doc: DocHost; ids: Record<string, string> } {
  const doc = new DocHost(createDefaultProject('Mix'), opts.catalog ?? automixCatalog(), { strict: true });
  const ex = <T>(cmd: string, args: unknown): T => {
    const r = doc.exec<T>(cmd, args, { actor: { kind: 'system' } });
    if (!r.ok) throw new Error(r.message);
    return r.data as T;
  };
  const p0 = doc.project;
  if (p0.channelOrder.length) ex('channels.remove', { ids: [...p0.channelOrder] });
  for (const id of p0.mixer.insertOrder) if (!p0.mixer.inserts[id].isMaster) ex('mixer.removeInsert', { id });
  const ids: Record<string, string> = {};
  for (const n of NAMES) {
    if (n === 'Vocals' && opts.vocals === false) continue;
    ids[n] = ex<{ id: string }>('mixer.addInsert', { name: n }).id;
  }
  if (opts.drumBus) {
    ids['Drum Bus'] = ex<{ id: string }>('mixer.addInsert', { name: 'Drum Bus' }).id;
    for (const n of ['Kick', 'Snare', 'Hats']) {
      ex('mixer.setRoute', { from: ids[n], to: ids['Drum Bus'], level: 1 });
      ex('mixer.setRoute', { from: ids[n], to: doc.project.mixer.masterId, level: null });
    }
  }
  return { doc, ids };
}

const bands = (mid: number, rel: Partial<Bands>): Bands => ({ sub: mid + (rel.sub ?? -10), low: mid + (rel.low ?? -3), lowMid: mid + (rel.lowMid ?? -1), mid, highMid: mid + (rel.highMid ?? -4), high: mid + (rel.high ?? -10) });

/** Typical stems: (lufs, peak, crest, band shape relative to the mids). */
export const PARTS: Record<PartName, { lufs: number; peak: number; crest: number; rel: Partial<Bands> }> = {
  Kick: { lufs: -16, peak: -4, crest: 12, rel: { sub: 8, low: 9, lowMid: -2, highMid: -8, high: -14 } },
  Bass: { lufs: -17, peak: -6, crest: 9, rel: { sub: 9, low: 7, lowMid: 0, highMid: -12, high: -20 } },
  Snare: { lufs: -18, peak: -5, crest: 14, rel: { sub: -12, low: -2, lowMid: 0, highMid: -2, high: -6 } },
  Hats: { lufs: -26, peak: -12, crest: 16, rel: { sub: -30, low: -20, lowMid: -12, highMid: 2, high: 4 } },
  Keys: { lufs: -22, peak: -10, crest: 12, rel: { sub: -10, low: -1, lowMid: 1, highMid: -5, high: -12 } },
  Lead: { lufs: -21, peak: -9, crest: 11, rel: { sub: -20, low: -6, lowMid: -2, highMid: -3, high: -10 } },
  Vocals: { lufs: -20, peak: -6, crest: 16, rel: { sub: -20, low: -4, lowMid: 0, highMid: -3, high: -11 } },
  'Drum Bus': { lufs: -13, peak: -2, crest: 12, rel: { sub: 5, low: 5, lowMid: -1, highMid: -3, high: -6 } },
};

export function insertMeasure(name: PartName, over: Partial<{ lufs: number; peak: number; crest: number; rel: Partial<Bands> }> = {}): InsertMeasure {
  const base = PARTS[name];
  const lufs = over.lufs ?? base.lufs;
  return { lufs, peakDb: over.peak ?? base.peak, crestDb: over.crest ?? base.crest, bands: bands(lufs - 3, { ...base.rel, ...(over.rel ?? {}) }), centroidHz: 1500 };
}

/** A measurement: the master's numbers + every insert's stem. */
export function measure(ids: Record<string, string>, over: { master?: Partial<PlanMeasure['master']>; inserts?: Partial<Record<PartName, Partial<{ lufs: number; peak: number; crest: number; rel: Partial<Bands> }>>>; gr?: PlanMeasure['gr'] } = {}): PlanMeasure {
  const inserts: PlanMeasure['inserts'] = {};
  for (const [name, id] of Object.entries(ids)) inserts[id] = insertMeasure(name as PartName, over.inserts?.[name as PartName] ?? {});
  return {
    master: { lufs: -14, truePeak: -2, peakDb: -2.2, crestDb: 11, lra: 6, tone: { sub: 6, low: 6.5, lowMid: -1, mid: 0, highMid: -5, high: -8 }, correlation: 0.5, ...(over.master ?? {}) },
    inserts,
    gr: over.gr ?? [],
  };
}
